\u0022\u002a\u0046\u0073\u007e\u007e\u0065\u0050\u006e\u006a\u0043\u0075\u0045\u0059\u003f\u003e\u0040\u0056\u0079\u0044\u003a\u005f\u005b\u0024\u0048\u0066\u0023\u0047\u0060\u005b\u007d\u0077\u0060\u0033\u0063\u0023\u007d\u002a\u0036\u002c\u0067\u0058\u0022\u004c\u004d\u0057\u006c\u0051\u0032\u0035\u0037\u003e\u004c\u002e\u005b\u004c\u0055\u003c\u0028\u0055\u0061\u0066\u0048\u0038\u002b\u0050\u005e\u0021\u006a\u005d\u0051\u002c\u0070\u0068\u0060\u0024\u0053\u0032\u006e\u0055\u0069\u003f\u0058\u0072\u004a\u0073\u0063\u006b\u006c\u0078\u0032\u0039\u0021\u0040\u006e\u0071\u004e\u0064\u0048\u0063\u0045\u0078\u0060\u004c\u002d\u0065\u0067\u004b\u004d\u0030\u0037\u003a\u0057\u007d\u0043\u002d\u005b\u0054\u0066\u0042\u0061\u0035\u0047\u004b\u0055\u0027\u005a\u0031\u003a\u0031\u0073\u0048\u003b\u0020\u0074\u002d\u0066\u0047\u004a\u0029\u0042\u006c\u006f\u0051\u0049\u0022\u005a\u0034\u0077\u002a\u0030\u005d\u0065\u0061\u0052\u002e\u0079\u0036\u0066\u002a\u002c\u005e\u003a\u006b\u0026\u007b\u0043\u0073\u0036\u0031\u004c\u006d\u006d\u004b\u0029\u0052\u0033\u0026\u0040\u007d\u003d\u0038\u0077\u0073\u0054\u0067\u0039\u005c\u004e\u0028\u003f\u007b\u0057\u0040\u0042\u0066\u005e\u0035\u006a\u0039\u0026\u0033\u005f\u004c\u005b\u007b\u007b\u004e\u0054\u0079\u0056\u003d\u0028\u0065\u0044\u0038\u0078\u0075\u0057\u0048\u0069\u0076\u0076\u0037\u004d\u0047\u0058\u007b\u0066\u0056\u0021\u0036\u0030\u006e\u007c\u0035\u0045\u005b\u0067\u006d\u0071\u0040\u0025\u006b\u0057\u0021\u0060\u0060\u0039\u0074\u0051\u0055\u0068\u0078\u0045\u003f\u007b\u0030\u006a\u006c\u0036\u0032\u005b\u0025\u004c\u002a\u0070\u0059\u006a\u007c\u0038\u0025\u004a\u0047\u0050\u0038\u0056\u0071\u002b\u0033\u0074\u0028\u0035\u0055\u0038\u0066\u0048\u0075\u0035\u003e\u005e\u0050\u004c\u0066\u0057\u005e\u004b\u0039\u0035\u004a\u0071\u005d\u0029\u0035\u0055\u0070\u0051\u0043\u0049\u002f\u0067\u0035\u007d\u006b\u0062\u0020\u004d\u007a\u0058\u0066\u0032\u003d\u005a\u0048\u0071\u0061\u0076\u007e\u005f\u002c\u0037\u0065\u006e\u0034\u0037\u0064\u0020\u002d\u004c\u003e\u006b\u0039\u0060\u007c\u0021\u005a\u0042\u002d\u0028\u0046\u003d\u0047\u0035\u0076\u006e\u0074\u004b\u002a\u007c\u003b\u007c\u003a\u0027\u0033\u006f\u004e\u0079\u0025\u0035\u0034\u005d\u0024\u005f\u0049\u0032\u002d\u0057\u006b\u0076\u003f\u004c\u0062\u0026\u002f\u002b\u006d\u0059\u0074\u007d\u003a\u0050\u003f\u0037\u0039\u006a\u007a\u0039\u0053\u0027\u0043\u004b\u0054\u004a\u0062\u0064\u0066\u0021\u006c\u002e\u005b\u0039\u0058\u0028\u0041\u007e\u0059\u0050\u0021\u0036\u0030\u006e\u004a\u0070\u0033\u0046\u0054\u003a\u0030\u0066\u006e\u0038\u005b\u003d\u003f\u0038\u0057\u007c\u006c\u0075\u0074\u003e\u0050\u0032\u0077\u0032\u002a\u006f\u002a\u007e\u0036\u0037\u0059\u003d\u006e\u0054\u0032\u0077\u003f\u002a\u0062\u006f\u0029\u0020\u0055\u006c\u003e\u0079\u0046\u005a\u003a\u004b\u0027\u0031\u0069\u0067\u0075\u003c\u007a\u0054\u005b\u0036\u006f\u007d\u0066\u0058\u0060\u006b\u0072\u0046\u0039\u007e\u007c\u0040\u0031\u0040\u0043\u0041\u003e\u0075\u0058\u0057\u003d\u004b\u0046\u0057\u005a\u0058\u006d\u004e\u0066\u007e\u002d\u007e\u0066\u0050\u006d\u0071\u0020\u0056\u0032\u006d\u003b\u0040\u005c\u0048\u0028\u007c\u0068\u0026\u006e\u0073\u006b\u0050\u004b\u003b\u0066\u0025\u003d\u0043\u0044\u005d\u007e\u002d\u0032\u0037\u006c\u007e\u0075\u0038\u007c\u005c\u0051\u0045\u003a\u0074\u004e\u007d\u006f\u0033\u0072\u0066\u0062\u0067\u007b\u0050\u0039\u0046\u003f\u0041\u004d\u0020\u003a\u0035\u002d\u004f\u002a\u0031\u007c\u0069\u002a\u006a\u006f\u0061\u0021\u0035\u0038\u006d\u0044\u0024\u006e\u006f\u0078\u0022\u0033\u0033\u002e\u0062\u0067\u006b\u005d\u007b\u002e\u0038\u003d\u006f\u003d\u0025\u0068\u0034\u0031\u0051\u0023\u005c\u0059\u0049\u0020\u0070\u005c\u0023\u0043\u004b\u005b\u0025\u0032\u007a\u0050\u007c\u0061\u0063\u0035\u0048\u007d\u0043\u0022\u0063\u0061\u0022\u0052\u0040\u006d\u0070\u0043\u004f\u0061\u0074\u002e\u0035\u0041\u007e\u0059\u0039\u0025\u005e\u0059\u005a\u005f\u0051\u0030\u005a\u0028\u007c\u0043\u0024\u006a\u0036\u0054\u005b\u0020\u003f\u007d\u0041\u0054\u003d\u004e\u0058\u0021\u0074\u004b\u003e\u0047\u0037\u0029\u007a\u0068\u0029\u0039\u0068\u0066\u0022\u004d\u0043\u006c\u0031\u003c\u004b\u0051\u0071\u0043\u0020\u0041\u004f\u0023\u0052\u0033\u002c\u0028\u003f\u0053\u0035\u0041\u007e\u0047\u004f\u002c\u0046\u0031\u0051\u0031\u0020\u002a\u0068\u003b\u007a\u0036\u006f\u0039\u004f\u0052\u003f\u0024\u0029\u0057\u0052\u0060\u006f\u003a\u005d\u0077\u0041\u0033\u004d\u0048\u004f\u0073\u0076\u0063\u0048\u0048\u0069\u0047\u0020\u007b\u003b\u003b\u0056\u004b\u0058\u005e\u005a\u005f\u004c\u0057\u0077\u0033\u0073\u0075\u0051\u0069\u006a\u005c\u0043\u0048\u0079\u0073\u002a\u0039\u0053\u0077\u0041\u007d\u0036\u0056\u002c\u0020\u0066\u005a\u0044\u0068\u003a\u0041\u002f\u0033\u0064\u003e\u006f\u0027\u002b\u002d\u0043\u0052\u0069\u0028\u007e\u0020\u0020\u004f\u0074\u0060\u0036\u004f\u0049\u004c\u0045\u002d\u006a\u004b\u002f\u0041\u003f\u0060\u0039\u0021\u0041\u0031\u006c\u0051\u007c\u0062\u0068\u006f\u0070\u0033\u0053\u002d\u0029\u0040\u0061\u007d\u0020\u0030\u0068\u0038\u004f\u0078\u004d\u005f\u006c\u0061\u0027\u0029\u004a\u0075\u0044\u0032\u0050\u005b\u004a\u0028\u002e\u0036\u0033\u007b\u0058\u003b\u0033\u003b\u0075\u0031\u006d\u0063\u004f\u0059\u0050\u005f\u005a\u006c\u003b\u0059\u0030\u0077\u0062\u0064\u0033\u0049\u005b\u0051\u0057\u0034\u0066\u0030\u006d\u0070\u006d\u002b\u0052\u006a\u0034\u0042\u0043\u003f\u004e\u005c\u003a\u005a\u0039\u0033\u004b\u0031\u005d\u0033\u0040\u007b\u006e\u0035\u0059\u005f\u005a\u0073\u0075\u003a\u0023\u0049\u007a\u0054\u003d\u0047\u0059\u0058\u0024\u005e\u007d\u002d\u0022\u0042\u0072\u002a\u0051\u003a\u004d\u007a\u0034\u0075\u004e\u004b\u0067\u0044\u004e\u0075\u005c\u0052\u0055\u004b\u006f\u0049\u0078\u006a\u002f\u002f\u0064\u004a\u006b\u0067\u0024\u007a\u0043\u0027\u0046\u0064\u006a\u006c\u0022\u0064\u0022\u0064\u005b\u003c\u0051\u0040\u0050\u0056\u005a\u0035\u0037\u0046\u0051\u003b\u0064\u0076\u0057\u0074\u0039\u003f\u006e\u0029\u0030\u0023\u007d\u0032\u002f\u0020\u0038\u0031\u0046\u0072\u004b\u0059\u0022\u006b\u0037\u0048\u007a\u004f\u0028\u0047\u0050\u0047\u0027\u0062\u004e\u002a\u002a\u003c\u0061\u003c\u002f\u0061\u0049\u0045\u0064\u0076\u0033\u0041\u0078\u006e\u0026\u0045\u0066\u004f\u002d\u0044\u003f\u002c\u0020\u004e\u0038\u006e\u0048\u0027\u006d\u0025\u007e\u004c\u004f\u0065\u004f\u0065\u0032\u0056\u002c\u0043\u0074\u004e\u002e\u004f\u005a\u0075\u0064\u004f\u0063\u0042\u005c\u005c\u006d\u0049\u0068\u002b\u0079\u0020\u0051\u004b\u0058\u0053\u002f\u004c\u007c\u006d\u002a\u0053\u0036\u003a\u0054\u006b\u0033\u006f\u0079\u0060\u002b\u0063\u0078\u0029\u0026\u006c\u0036\u006e\u0036\u0075\u0032\u0047\u0051\u0068\u003f\u0052\u003c\u0049\u0057\u0031\u0023\u006d\u0021\u0074\u0026\u002b\u0022\u005e\u0047\u006f\u0035\u0026\u0044\u0027\u0035\u0033\u005a\u0028\u007b\u0029\u0063\u0039\u0039\u004e\u0026\u003b\u0066\u0061\u0055\u0039\u0070\u006a\u0050\u0073\u0039\u0036\u0056\u0031\u007d\u005e\u0021\u005f\u0033\u002d\u0046\u0060\u002f\u0056\u0070\u007a\u0055\u0073\u0033\u0072\u006d\u0031\u0068\u0055\u0020\u003a\u003f\u007c\u0074\u0034\u004a\u0034\u0071\u0063\u0074\u0040\u0053\u002b\u0068\u0038\u005b\u0077\u007b\u007d\u0060\u0052\u0053\u005c\u0059\u0033\u0055\u005f\u0029\u0050\u003c\u0031\u0055\u003d\u0036\u007e\u0055\u0054\u0079\u005d\u0046\u0054\u0055\u0049\u0040\u005c\u0064\u0050\u0033\u0045\u0029\u0040\u006f\u0049\u0061\u0072\u0064\u0071\u0044\u0048\u0054\u006f\u006b\u004d\u004e\u0028\u0078\u0056\u0054\u007c\u0041\u002c\u0071\u0037\u0037\u002b\u0073\u0032\u0042\u005f\u0027\u0075\u0027\u0061\u0067\u007c\u0062\u002f\u0076\u0043\u004d\u002e\u0056\u0043\u0078\u007e\u006d\u007a\u0034\u005c\u0076\u0022\u003f\u005c\u0025\u0078\u0040\u007b\u0051\u0079\u0058\u003a\u0077\u0023\u0076\u0034\u002d\u0034\u0056\u003b\u004e\u0024\u0023\u002f\u0053\u0040\u0027\u004f\u002d\u0059\u0037\u0047\u0029\u0058\u006c\u0034\u0042\u003d\u005f\u0020\u0030\u0064\u002f\u0043\u0048\u002f\u002f\u0031\u0063\u0058\u0055\u0079\u0074\u0034\u0025\u0029\u004a\u0055\u0061\u0046\u0065\u005a\u0035\u0072\u0058\u0030\u0028\u004f\u0034\u006e\u003c\u0032\u006f\u0072\u0050\u0029\u006e\u0031\u006e\u0024\u003d\u0059\u007b\u0041\u007b\u003a\u003b\u0077\u0066\u006c\u0075\u0042\u005d\u007c\u0050\u0059\u0038\u005b\u0061\u003f\u005e\u0037\u005a\u006c\u007a\u0041\u0071\u007e\u0043\u0020\u007b\u0036\u0076\u003c\u005b\u0037\u0072\u007e\u0042\u007a\u0020\u0066\u003e\u0036\u0027\u0035\u0047\u004a\u0029\u0051\u007b\u0049\u005e\u0042\u005d\u0072\u0027\u004b\u0061\u006c\u0078\u005a\u0055\u0056\u0022\u0078\u005d\u0072\u0046\u007d\u0049\u002b\u0028\u0067\u002a\u002a\u006b\u0061\u002b\u0025\u0054\u0022\u0071\u0047\u0023\u0035\u0042\u0040\u0043\u0047\u0028\u0039\u0079\u002c\u0051\u005d\u0024\u004d\u0061\u004f\u0049\u0075\u005e\u0071\u004e\u005d\u0057\u0026\u002f\u003a\u0073\u0024\u0062\u0030\u004c\u005d\u0028\u0068\u0030\u004d\u003e\u0033\u0061\u005b\u003b\u006d\u0053\u0062\u0021\u0051\u0048\u0043\u0038\u004a\u003b\u0076\u0075\u007a\u003c\u0053\u0020\u006b\u003b\u0068\u004c\u0048\u0045\u006d\u0038\u0054\u0058\u0067\u004f\u0031\u0034\u006a\u007b\u0034\u0021\u004b\u004a\u0070\u0038\u0066\u0066\u007c\u0025\u0068\u0077\u005f\u0025\u0033\u0024\u005c\u0036\u004c\u006a\u0056\u0064\u0043\u005b\u004c\u003b\u0024\u005e\u005e\u0058\u0021\u0047\u0050\u0063\u0077\u005f\u005a\u0051\u0025\u0024\u007b\u0078\u006d\u004c\u005b\u0050\u002e\u0072\u0058\u002d\u004a\u002e\u0072\u003d\u0045\u0039\u002a\u0071\u006a\u0070\u004c\u0053\u0079\u0071\u0049\u003b\u0039\u0064\u005b\u0060\u0073\u0037\u0023\u005b\u0074\u0075\u0057\u002d\u004c\u0021\u005f\u0023\u0046\u0033\u0036\u006b\u006c\u0038\u0072\u0061\u0048\u005c\u004a\u0059\u004c\u004b\u0054\u0032\u0042\u0065\u0070\u0049\u0061\u0043\u005a\u003a\u0050\u0037\u0073\u0052\u0058\u0068\u0048\u003d\u0029\u0029\u005c\u0074\u004f\u0052\u0037\u0065\u0046\u0032\u0043\u0038\u0029\u0036\u0026\u0038\u0067\u0031\u0076\u0068\u0073\u007a\u002c\u0076\u007e\u0067\u007b\u003c\u0055\u0026\u0078\u004b\u0061\u0052\u0077\u0041\u0069\u0051\u004c\u0070\u0063\u0075\u005f\u0071\u0021\u0064\u0032\u0066\u0075\u0075\u004c\u0042\u004c\u006b\u002c\u0056\u002f\u006e\u0033\u0076\u005e\u0034\u007c\u007c\u005a\u0058\u003d\u002d\u007a\u002e\u005a\u007a\u007b\u0024\u005d\u0026\u0028\u0061\u0057\u0074\u0023\u0070\u0077\u0074\u0068\u0038\u0040\u0021\u0042\u0026\u006d\u0054\u0079\u006d\u004a\u007b\u003b\u0067\u0047\u0043\u004c\u005a\u006e\u0030\u007d\u0037\u0071\u0057\u0070\u005f\u0038\u002b\u0026\u0035\u002b\u005c\u0030\u0079\u005a\u0037\u0060\u0076\u0047\u007d\u0041\u0047\u0049\u004d\u005b\u0062\u003a\u0069\u004f\u0032\u003c\u007b\u0044\u0062\u003b\u0038\u0068\u003e\u004b\u0053\u0079\u003f\u0044\u0065\u002c\u0043\u0067\u003d\u0023\u006f\u005e\u0038\u005f\u0059\u0044\u0068\u002f\u0035\u003b\u0059\u002c\u0050\u005f\u004d\u002f\u0070\u0048\u005c\u002a\u0066\u0055\u005b\u003a\u0049\u0067\u0050\u0040\u0072\u0073\u004c\u0053\u0052\u004f\u0062\u0050\u0069\u0047\u0031\u0032\u0055\u005c\u0043\u0049\u0028\u0023\u002a\u0067\u0067\u0028\u003d\u002f\u0037\u0035\u0030\u0062\u006b\u0073\u0074\u0024\u007c\u0035\u0027\u0063\u006d\u0031\u003c\u0029\u0063\u005c\u0052\u004b\u0021\u006a\u0027\u0076\u0047\u0026\u0042\u005e\u0060\u0067\u0029\u0049\u0031\u006e\u006f\u0025\u002c\u0034\u007c\u0059\u0071\u0062\u0047\u005e\u0064\u004b\u0052\u0074\u0028\u0048\u0079\u0062\u0042\u0070\u0038\u0064\u0063\u0026\u0045\u0046\u0055\u0053\u003d\u0070\u0026\u003e\u0049\u007e\u005c\u0075\u007a\u0060\u006f\u0052\u0061\u0063\u0077\u0062\u003f\u0024\u003e\u0042\u0054\u007b\u0036\u005f\u002d\u002c\u0022\u0064\u0077\u0044\u0063\u0027\u005c\u003e\u0020\u0074\u004e\u0029\u003d\u0071\u0053\u0055\u0044\u007e\u006d\u0047\u0037\u0056\u003f\u0071\u0037\u0054\u0068\u0063\u0021\u0059\u0072\u003a\u0044\u0029\u0047\u003b\u0033\u0029\u0038\u0040\u007c\u004a\u0057\u005c\u005d\u0037\u004c\u003a\u0030\u0078\u0042\u006c\u0034\u0037\u007e\u0054\u0027\u0039\u004b\u0056\u006f\u0075\u0036\u0044\u0071\u0074\u007d\u003e\u007d\u0026\u0071\u006f\u004d\u0039\u003e\u0062\u0067\u007b\u0078\u006d\u0051\u003f